            cin >> S[i];
        }

        vector<long long> dp(n + 1, 0);
        for (int v : S) {
            if (v == 1) {
                dp[1] = (dp[1] + 1) % MOD;
            } else {
                dp[v] = (dp[v] + dp[v - 1]) % MOD;
            }
        }

        long long ans = 0;
        for (int x = 1; x <= n; ++x) {
            ans = (ans + x * dp[x]) % MOD;
        }
        cout << ans << '\n';
    }

    return 0;
}
